INSERT INTO changelog (title, body, created_at) VALUES ('Заявки — у власного бота клієнта', 'Тепер заявки можна слати не лише в нашу Telegram-групу, а й у бота самого клієнта. Тоді менеджерам клієнта пише їхній бот з кнопками «Взяли / Якісна / Сміття».
Як: клієнт → Meta → «Заявки» → «Куди йдуть заявки» → «Бот клієнта» → встав токен бота з @BotFather → «Підключити». Зʼявиться посилання-запрошення: скинь його менеджерам, хто відкриє і натисне Start — отримуватиме заявки (відписка /stop). Перевір кнопкою «Тестова заявка». Галочками обираєш, куди слати: у групу, у бота або в обидва місця. Натиснули кнопку в одному місці — оновиться скрізь.
Галочка біля сторінки в Конектори → Meta тепер називається «надсилати» (вмикає надсилання заявок цієї сторінки).
Обмеження: якщо бот клієнта вже працює в іншому сервісі, після підключення він там перестане отримувати повідомлення — система попередить. Перевірено на імітації Telegram.', datetime('now'));
